   listener(event.payload, function acknowledge(value) {\\n        acknowledgements.push(value);\\n        advanceListener();\\n      });\\n    }\\n\\n    advanceListener();\\n  }\\n\\n  advanceEvent();\\n}\\n\\nmodule.exports = runEventSequence;\",\"known_bad_label\":\"Stores event progress and collected results in module-level variables, so overlapping runs overwrite each other's callback state.\"},{\"id\":\"cap-v2-callbacks_and_events-javascript-repair-02\",\"problem\":\"Repair the implementation below. Export exactly one factory function, `createSignalHub`, with `module.exports = createSignalHub`.\\n\\nEach call to `createSignalHub()` returns an independent object with two methods:\\n\\n- `on(name, listener)` registers a listener for that signal name.\\n- `emit(name, payload, done)` invokes the hub's listeners for that name in registration order. Each listener receives `(payload, acknowledge)`. The next listener must wait until the current listener calls `acknowledge(value)`. When all listeners have acknowledged, call `done(values)` exactly once with acknowledgement values in listener order. If there are no listeners, call `done([])`.\\n\\nRegistrations must be isolated per hub: registering on one hub must never affect another hub. Assume every listener acknowledges exactly once.\\n\\nUse only standard JavaScript. Do not access the filesystem, network, clock, randomness, packages, or frameworks. Return a corrected complete source file.\\n\\n```javascript\\nconst subscriptions = Object.create(null);\\n\\nfunction createSignalHub() {\\n  function on(name, listener) {\\n    if (!subscriptions[name]) {\\n      subscriptions[name] = [];\\n    }\\n    subscriptions[name].push(listener);\\n  }\\n\\n  function emit(name, payload, done) {\\n    const listeners = subscriptions[name] || [];\\n    const values = [];\\n    let index = 0;\\n\\n    function continueEmission() {\\n      if (index === listeners.length) {\\n        done(values);\\n        return;\\n      }\\n\\n      const listener = listeners[index++];\\n      listener(payload, function acknowledge(value) {\\n        values.push(value);\\n        continueEmission();\\n      });\\n    }\\n\\n    continueEmission();\\n  }\\n\\n  return { on, emit };\\n}\\n\\nmodule.exports = createSignalHub;\\n```\",\"reference_code\":\"function createSignalHub() {\\n  const subscriptions = Object.create(null);\\n\\n  function on(name, listener) {\\n    if (!subscriptions[name]) {\\n      subscriptions[name] = [];\\n    }\\n    subscriptions[name].push(listener);\\n  }\\n\\n  function emit(name, payload, done) {\\n    const listeners = subscriptions[name] || [];\\n    const values = [];\\n    let index = 0;\\n\\n    function continueEmission() {\\n      if (index === listeners.length) {\\n        done(values);\\n        return;\\n      }\\n\\n      const listener = listeners[index++];\\n      listener(payload, function acknowledge(value) {\\n        values.push(value);\\n        continueEmission();\\n      });\\n    }\\n\\n    continueEmission();\\n  }\\n\\n  return { on, emit };\\n}\\n\\nmodule.exports = createSignalHub;\",\"known_bad_code\":\"const subscriptions = Object.create(null);\\n\\nfunction createSignalHub() {\\n  function on(name, listener) {\\n    if (!subscriptions[name]) {\\n      subscriptions[name] = [];\\n    }\\n    subscriptions[name].push(listener);\\n  }\\n\\n  function emit(name, payload, done) {\\n    const listeners = subscriptions[name] || [];\\n    const values = [];\\n    let index = 0;\\n\\n    function continueEmission() {\\n      if (index === listeners.length) {\\n        done(values);\\n        return;\\n      }\\n\\n      const listener = listeners[index++];\\n      listener(payload, function acknowledge(value) {\\n        values.push(value);\\n        continueEmission();\\n      });\\n    }\\n\\n    continueEmission();\\n  }\\n\\n  return { on, emit };\\n}\\n\\nmodule.exports = createSignalHub;\",\"known_bad_label\":\"Keeps the subscription registry at module scope, causing all signal-hub instances to share listeners instead of isolating their state.\"},{\"id\":\"cap-v2-graph_and_tree-javascript-generation-01\",\"problem\":\"Implement and export exactly one function, `resolveDependencyOrder`, using `module.exports = resolveDependencyOrder`.\\n\\n`resolveDependencyOrder(graph, roots)` receives a finite acyclic dependency graph and an array of root node names. `graph[node]` is an array of that node's direct dependencies; a referenced node absent from `graph` is a leaf.\\n\\nReturn a single array containing every node reachable from `roots` in dependency-first order: all dependencies of a node must appear before that node. Traverse roots and dependency arrays from left to right. Repeated roots, duplicate dependency entries, and dependencies shared by multiple nodes must produce only one occurrence of that node. The first traversal encounter determines its position.\\n\\nFor example, if an already resolved dependency is encountered again, skip it and continue traversal rather than adding a duplicate.\\n\\nUse only standard JavaScript. Do not access the filesystem, network, clock, randomness, packages, or frameworks. Return a complete source file without tests.\",\"reference_code\":\"function resolveDependencyOrder(graph, roots) {\\n  const resolved = new Set();\\n  const order = [];\\n\\n  function visit(node) {\\n    if (resolved.has(node)) {\\n      return;\\n    }\\n\\n    resolved.add(node);\\n    const dependencies = graph[node] || [];\\n\\n    for (const dependency of dependencies) {\\n      visit(dependency);\\n    }\\n\\n    order.push(node);\\n  }\\n\\n  for (const root of roots) {\\n    visit(root);\\n  }\\n\\n  return order;\\n}\\n\\nmodule.exports = resolveDependencyOrder;\",\"known_bad_code\":\"function resolveDependencyOrder(graph, roots) {\\n  const order = [];\\n\\n  function visit(node) {\\n    const dependencies = graph[node] || [];\\n\\n    for (const dependency of dependencies) {\\n      visit(dependency);\\n    }\\n\\n    order.push(node);\\n  }\\n\\n  for (const root of roots) {\\n    visit(root);\\n  }\\n\\n  return order;\\n}\\n\\nmodule.exports = resolveDependencyOrder;\",\"known_bad_label\":\"Does not track resolved nodes, so repeated roots, duplicate edges, and shared dependencies are emitted multiple times.\"},{\"id\":\"cap-v2-graph_and_tree-javascript-generation-02\",\"problem\":\"Implement and export exactly one function, `flattenHierarchy`, using `module.exports = flattenHierarchy`.\\n\\n`flattenHierarchy(root)` receives a finite hierarchy whose nodes have `id`, `label`, and `children` properties. `children` is an array of more nodes. Traverse the hierarchy in depth-first preorder, visiting children from left to right.\\n\\nReturn an array of records shaped as `{ id, label, depth, parentId }`. The root has depth `0` and parentId `null`; each child has its parent's depth plus one and its parent's id.\\n\\nNode ids are identity keys and may occur more than once, including through repeated references. Emit only the first occurrence of each id. When a duplicate id is encountered, skip that occurrence and its entire subtree. Thus every id appears at most once, and the first preorder encounter supplies its label, depth, and parentId.\\n\\nUse only standard JavaScript. Do not access the filesystem, network, clock, randomness, packages, or frameworks. Return a complete source file without tests.\",\"reference_code\":\"function flattenHierarchy(root) {\\n  const records = [];\\n  const visitedIds = new Set();\\n\\n  function visit(node, depth, parentId) {\\n    if (visitedIds.has(node.id)) {\\n      return;\\n    }\\n\\n    visitedIds.add(node.id);\\n    records.push({\\n      id: node.id,\\n      label: node.label,\\n      depth,\\n      parentId\\n    });\\n\\n    for (const child of node.children) {\\n      visit(child, depth + 1, node.id);\\n    }\\n  }\\n\\n  visit(root, 0, null);\\n  return records;\\n}\\n\\nmodule.exports = flattenHierarchy;\",\"known_bad_code\":\"function flattenHierarchy(root) {\\n  const records = [];\\n\\n  function visit(node, depth, parentId) {\\n    records.push({\\n      id: node.id,\\n      label: node.label,\\n      depth,\\n      parentId\\n    });\\n\\n    for (const child of node.children) {\\n      visit(child, depth + 1, node.id);\\n    }\\n  }\\n\\n  visit(root, 0, null);\\n  return records;\\n}\\n\\nmodule.exports = flattenHierarchy;\",\"known_bad_label\":\"Traverses every occurrence without tracking node ids, so duplicate or repeatedly referenced nodes are emitted again instead of having their later subtrees skipped.\"},{\"id\":\"cap-v2-graph_and_tree-javascript-repair-01\",\"problem\":\"Repair the implementation below. Export exactly one function, `extractReachableGraph`, with `module.exports = extractReachableGraph`.\\n\\n`extractReachableGraph(graph, start)` receives a finite directed graph represented as an object whose values are arrays of outgoing neighbor names. A referenced node absent from `graph` is a leaf. Traverse from `start` and return an object containing every reachable node as a key and that node's outgoing-neighbor array as its value.\\n\\nThe returned graph must be structurally independent of the input: every returned neighbor array must be a fresh array. Mutating a returned array must not change `graph`, and mutating an input neighbor array after the call must not change the returned graph. Do not mutate the input during extraction.\\n\\nUse only standard JavaScript. Do not access the filesystem, network, clock, randomness, packages, or frameworks. Return a corrected complete source file.\\n\\n```javascript\\nfunction extractReachableGraph(graph, start) {\\n  const result = {};\\n  const visited = new Set();\\n\\n  function visit(node) {\\n    if (visited.has(node)) {\\n      return;\\n    }\\n\\n    visited.add(node);\\n    const neighbors = graph[node] || [];\\n    result[node] = neighbors;\\n\\n    for (const neighbor of neighbors) {\\n      visit(neighbor);\