{"items":[{"id":"cap-v2-callbacks_and_events-javascript-repair-01","test_code":"'use strict';

const assert = require('node:assert');
const runEventSequence = require('./solution');

assert.strictEqual(typeof runEventSequence, 'function');

{
  const calls = [];
  let doneCalls = 0;
  let result;

  runEventSequence(
    [
      { type: 'alpha', payload: 4 },
      { type: 'unhandled', payload: 99 },
      { type: 'beta', payload: 7 }
    ],
    {
      alpha: [
        (payload, acknowledge) => {
          calls.push(['alpha-1', payload]);
          acknowledge(payload + 1);
        },
        (payload, acknowledge) => {
          calls.push(['alpha-2', payload]);
          acknowledge(payload * 2);
        }
      ],
      beta: [
        (payload, acknowledge) => {
          calls.push(['beta-1', payload]);
          acknowledge(String(payload));
        }
      ]
    },
    values => {
      doneCalls += 1;
      result = values;
    }
  );

  assert.deepStrictEqual(calls, [
    ['alpha-1', 4],
    ['alpha-2', 4],
    ['beta-1', 7]
  ]);
  assert.deepStrictEqual(result, [
    { type: 'alpha', acknowledgements: [5, 8] },
    { type: 'unhandled', acknowledgements: [] },
    { type: 'beta', acknowledgements: ['7'] }
  ]);
  assert.strictEqual(doneCalls, 1);
}

{
  let doneCalls = 0;
  let result;

  runEventSequence([], {}, values => {
    doneCalls += 1;
    result = values;
  });

  assert.deepStrictEqual(result, []);
  assert.strictEqual(doneCalls, 1);
}

{
  const executionOrder = [];
  let acknowledgeA1;
  let acknowledgeA2;
  let acknowledgeB;
  let resultA;
  let resultB;
  let doneA = 0;
  let doneB = 0;

  runEventSequence(
    [
      { type: 'work', payload: 'A1' },
      { type: 'work', payload: 'A2' }
    ],
    {
      work: [
        (payload, acknowledge) => {
          executionOrder.push(payload);
          if (payload === 'A1') acknowledgeA1 = acknowledge;
          else acknowledgeA2 = acknowledge;
        }
      ]
    },
    values => {
      doneA += 1;
      resultA = values;
    }
  );

  runEventSequence(
    [{ type: 'work', payload: 'B' }],
    {
      work: [
        (payload, acknowledge) => {
          executionOrder.push(payload);
          acknowledgeB = acknowledge;
        }
      ]
    },
    values => {
      doneB += 1;
      resultB = values;
    }
  );

  assert.deepStrictEqual(executionOrder, ['A1', 'B']);
  assert.strictEqual(acknowledgeA2, undefined);
  assert.strictEqual(resultA, undefined);
  assert.strictEqual(resultB, undefined);

  acknowledgeB('ack-B');
  assert.deepStrictEqual(resultB, [
    { type: 'work', acknowledgements: ['ack-B'] }
  ]);
  assert.strictEqual(resultA, undefined);

  acknowledgeA1('ack-A1');
  assert.deepStrictEqual(executionOrder, ['A1', 'B', 'A2']);
  assert.strictEqual(resultA, undefined);

  acknowledgeA2('ack-A2');
  assert.deepStrictEqual(resultA, [
    { type: 'work', acknowledgements: ['ack-A1'] },
    { type: 'work', acknowledgements: ['ack-A2'] }
  ]);
  assert.strictEqual(doneA, 1);
  assert.strictEqual(doneB, 1);
}
"},{"id":"cap-v2-callbacks_and_events-javascript-repair-02","test_code":"'use strict';

const assert = require('node:assert');
const createSignalHub = require('./solution');

assert.strictEqual(typeof createSignalHub, 'function');

{
  const hub = createSignalHub();
  const calls = [];
  let firstAcknowledge;
  let secondAcknowledge;
  let result;
  let doneCalls = 0;

  hub.on('update', (payload, acknowledge) => {
    calls.push(['first', payload]);
    firstAcknowledge = acknowledge;
  });
  hub.on('update', (payload, acknowledge) => {
    calls.push(['second', payload]);
    secondAcknowledge = acknowledge;
  });

  const payload = { value: 3 };
  hub.emit('update', payload, values => {
    doneCalls += 1;
    result = values;
  });

  assert.deepStrictEqual(calls, [['first', payload]]);
  assert.strictEqual(secondAcknowledge, undefined);
  assert.strictEqual(result, undefined);

  firstAcknowledge('one');
  assert.deepStrictEqual(calls, [
    ['first', payload],
    ['second', payload]
  ]);
  assert.strictEqual(result, undefined);

  secondAcknowledge('two');
  assert.deepStrictEqual(result, ['one', 'two']);
  assert.strictEqual(doneCalls, 1);
}

{
  const hub = createSignalHub();
  let doneCalls = 0;
  let result;

  hub.emit('missing', 10, values => {
    doneCalls += 1;
    result = values;
  });

  assert.deepStrictEqual(result, []);
  assert.strictEqual(doneCalls, 1);
}

{
  const firstHub = createSignalHub();
  const secondHub = createSignalHub();
  const calls = [];
  let firstResult;
  let secondResult;

  firstHub.on('signal', (payload, acknowledge) => {
    calls.push(['first-hub', payload]);
    acknowledge('first-only');
  });
  secondHub.on('signal', (payload, acknowledge) => {
    calls.push(['second-hub', payload]);
    acknowledge('second-only');
  });

  firstHub.emit('signal', 'A', values => {
    firstResult = values;
  });
  secondHub.emit('signal', 'B', values => {
    secondResult = values;
  });

  assert.deepStrictEqual(calls, [
    ['first-hub', 'A'],
    ['second-hub', 'B']
  ]);
  assert.deepStrictEqual(firstResult, ['first-only']);
  assert.deepStrictEqual(secondResult, ['second-only']);
}

{
  const hub = createSignalHub();
  const pending = Object.create(null);
  const starts = [];
  let resultX;
  let resultY;

  hub.on('job', (payload, acknowledge) => {
    starts.push(['first', payload]);
    pending['first-' + payload] = acknowledge;
  });
  hub.on('job', (payload, acknowledge) => {
    starts.push(['second', payload]);
    pending['second-' + payload] = acknowledge;
  });

  hub.emit('job', 'X', values => {
    resultX = values;
  });
  hub.emit('job', 'Y', values => {
    resultY = values;
  });

  assert.deepStrictEqual(starts, [
    ['first', 'X'],
    ['first', 'Y']
  ]);

  pending['first-Y']('Y1');
  pending['second-Y']('Y2');
  assert.deepStrictEqual(resultY, ['Y1', 'Y2']);
  assert.strictEqual(resultX, undefined);

  pending['first-X']('X1');
  pending['second-X']('X2');
  assert.deepStrictEqual(resultX, ['X1', 'X2']);
}
"},{"id":"cap-v2-graph_and_tree-javascript-generation-01","test_code":"'use strict';

const assert = require('node:assert');
const resolveDependencyOrder = require('./solution');

assert.strictEqual(typeof resolveDependencyOrder, 'function');

{
  const graph = {
    app: ['left', 'right', 'left'],
    left: ['shared', 'leaf'],
    right: ['shared'],
    shared: []
  };
  const snapshot = JSON.parse(JSON.stringify(graph));

  const result = resolveDependencyOrder(
    graph,
    ['app', 'right', 'standalone', 'app']
  );

  assert.deepStrictEqual(result, [
    'shared',
    'leaf',
    'left',
    'right',
    'app',
    'standalone'
  ]);
  assert.deepStrictEqual(graph, snapshot);
}

assert.deepStrictEqual(resolveDependencyOrder({}, []), []);
assert.deepStrictEqual(resolveDependencyOrder({}, ['missing', 'missing']), ['missing']);

{
  const graph = {
    first: ['common'],
    second: ['common', 'secondLeaf'],
    common: ['base'],
    base: []
  };

  assert.deepStrictEqual(
    resolveDependencyOrder(graph, ['first', 'second']),
    ['base', 'common', 'first', 'secondLeaf', 'second']
  );
  assert.deepStrictEqual(
    resolveDependencyOrder(graph, ['second', 'first']),
    ['base', 'common', 'secondLeaf', 'second', 'first']
  );
  assert.deepStrictEqual(
    resolveDependencyOrder(graph, ['first', 'second']),
    ['base', 'common', 'first', 'secondLeaf', 'second']
  );
}

{
  const graph = Object.create(null);
  graph.root = ['toString', '__proto__'];
  graph.__proto__ = [];

  assert.deepStrictEqual(
    resolveDependencyOrder(graph, ['root']),
    ['toString', '__proto__', 'root']
  );
}
