const assert = require('node:assert');
const flattenHierarchy = require('./solution');

assert.strictEqual(typeof flattenHierarchy, 'function');

{
  const root = {
    id: 'root',
    label: 'Root',
    children: [
      {
        id: 'a',
        label: 'Alpha',
        children: [
          { id: 'x', label: 'First X', children: [] }
        ]
      },
      {
        id: 'a',
        label: 'Duplicate Alpha',
        children: [
          { id: 'hidden', label: 'Must Be Skipped', children: [] }
        ]
      },
      {
        id: 'b',
        label: 'Beta',
        children: [
          { id: 'x', label: 'Duplicate X', children: [] },
          { id: 'z', label: 'Zulu', children: [] }
        ]
      }
    ]
  };
  const snapshot = JSON.parse(JSON.stringify(root));

  assert.deepStrictEqual(flattenHierarchy(root), [
    { id: 'root', label: 'Root', depth: 0, parentId: null },
    { id: 'a', label: 'Alpha', depth: 1, parentId: 'root' },
    { id: 'x', label: 'First X', depth: 2, parentId: 'a' },
    { id: 'b', label: 'Beta', depth: 1, parentId: 'root' },
    { id: 'z', label: 'Zulu', depth: 2, parentId: 'b' }
  ]);
  assert.deepStrictEqual(root, snapshot);
}

{
  const leaf = { id: 0, label: '', children: [] };
  assert.deepStrictEqual(flattenHierarchy(leaf), [
    { id: 0, label: '', depth: 0, parentId: null }
  ]);
}

{
  const shared = {
    id: 'shared',
    label: 'Shared',
    children: [
      { id: 'inside', label: 'Inside', children: [] }
    ]
  };
  const root = {
    id: 'r',
    label: 'R',
    children: [
      {
        id: 'left',
        label: 'Left',
        children: [shared]
      },
      {
        id: 'right',
        label: 'Right',
        children: [shared]
      }
    ]
  };

  const expected = [
    { id: 'r', label: 'R', depth: 0, parentId: null },
    { id: 'left', label: 'Left', depth: 1, parentId: 'r' },
    { id: 'shared', label: 'Shared', depth: 2, parentId: 'left' },
    { id: 'inside', label: 'Inside', depth: 3, parentId: 'shared' },
    { id: 'right', label: 'Right', depth: 1, parentId: 'r' }
  ];

  assert.deepStrictEqual(flattenHierarchy(root), expected);
  assert.deepStrictEqual(flattenHierarchy(root), expected);
}

{
  const root = {
    id: '__proto__',
    label: 'Prototype-like id',
    children: [
      { id: 'toString', label: 'Method-like id', children: [] }
    ]
  };

  assert.deepStrictEqual(flattenHierarchy(root), [
    {
      id: '__proto__',
      label: 'Prototype-like id',
      depth: 0,
      parentId: null
    },
    {
      id: 'toString',
      label: 'Method-like id',
      depth: 1,
      parentId: '__proto__'
    }
