const annotatePathTotals = (root) => {
  const visit = (node, parentTotal) => {
    const result = {
      ...node,
      pathTotal: parentTotal + node.value
    };

    result.children = node.children;
    for (let i = 0; i < result.children.length; i += 1) {
      result.children[i] = visit(result.children[i], result.pathTotal);
    }

    return result;
  };

  return visit(root, 0);
};

module.exports = { annotatePathTotals };
